    "new": "  // Handle unexpected permission responses by looking up the unresolved tool
  // call in the transcript and executing it
  const handledOrphanedToolUseIds = new Set<string>()
  // `findUnresolvedToolUse` deja `message.id` opcional (el mensaje siempre lo
  // trae, pero el tipo no lo exige); se envuelve para producir el
  // `OrphanedAssistantMessage` que `handleOrphanedPermissionResponse` declara,
  // con una guarda que el propio callback ya asume al leer
  // `assistantMessage.message.id`.
  const findUnresolvedToolUseForOrphanedPermission = async (
    toolUseID: string,
  ): Promise<OrphanedAssistantMessage | null> => {
    const assistantMessage = await findUnresolvedToolUse(toolUseID)
    const id = assistantMessage?.message.id
    if (!assistantMessage || typeof id !== 'string') {
      return null
    }
    return { ...assistantMessage, message: { ...assistantMessage.message, id } }
  }
  structuredIO.setUnexpectedResponseCallback(async message => {
    await handleOrphanedPermissionResponse({
      message,
      handledToolUseIds: handledOrphanedToolUseIds,
      onEnqueued: () => {
        // The first message of a session might be the orphaned permission
        // check rather than a user prompt, so kick off the loop.
        void run()
      },
      deps: {
        findUnresolvedToolUse: findUnresolvedToolUseForOrphanedPermission,
        enqueue,
        logDebug: logForDebugging,
      },
    })
  })"}
